"use strict";(self.webpackChunkultimatelearning=self.webpackChunkultimatelearning||[]).push([[467],{8467:e=>{e.exports=JSON.parse('{"topic":{"id":"inheritance-polymorphism","title":"Inheritance & Polymorphism (Deep Dive)","overviewSimple":"Imagine your younger sibling borrowing your toys \u2014 they reuse what you already have. That\u2019s inheritance. Now imagine the same toy making different sounds when different kids press the button \u2014 that\u2019s polymorphism.","overviewTechnical":["Inheritance allows one class to acquire fields/methods of another using \'extends\'.","Polymorphism enables multiple forms through method overriding and overloading.","Dynamic method dispatch enables runtime polymorphism.","super keyword refers to parent class members.","Constructors do not inherit but can be called using super()."],"story":"A family shared skills from generation to generation. Each new member improved old skills and added their own. This is similar to inheritance and polymorphism in Java.","realWorldAnalogy":"A smartphone brand releases new models every year. They all share core features but behave differently \u2014 just like polymorphism.","keyPoints":["Child class extends parent class","Method overriding enables runtime behavior","super calls parent methods","Java supports single inheritance"],"exampleSimple":"class Animal {\\n    void sound() { System.out.println(\\"Animal sound\\"); }\\n}\\nclass Dog extends Animal {\\n    void sound() { System.out.println(\\"Bark\\"); }\\n}","exampleTechnical":["class Vehicle {\\n    void start() { System.out.println(\\"Vehicle starts\\"); }\\n}\\n\\nclass Car extends Vehicle {\\n    @Override\\n    void start() { System.out.println(\\"Car starts with key\\"); }\\n}\\n\\npublic class Main {\\n    public static void main(String[] args) {\\n        Vehicle v = new Car();\\n        v.start();\\n    }\\n}","class Shape {\\n    double area() { return 0; }\\n}\\n\\nclass Circle extends Shape {\\n    double radius;\\n    Circle(double r) { this.radius = r; }\\n    @Override\\n    double area() { return Math.PI * radius * radius; }\\n}\\n\\npublic class Test {\\n    public static void main(String[] args) {\\n        Shape s = new Circle(5);\\n        System.out.println(s.area());\\n    }\\n}"],"extraNotes":["Java does not support multiple inheritance via classes.","Interfaces allow type-based polymorphism.","Use @Override to avoid accidental overloading."],"bestPracticesSimple":["Only inherit when classes are truly related","Use simple method names"],"bestPracticesAdvanced":["Prefer composition over inheritance","Avoid deep inheritance chains","Apply interfaces to achieve flexible polymorphism"]}}')}}]);